 for combo in combinations(options,k):
  ids=[opt['id'] for opt in combo]
  owners=[opt['owner'] for opt in combo]
  cats=[opt['category'] for opt in combo]
  # Check unique owners
  if len(set(owners))!=len(owners):
   continue
  # Check cover categories
  covers=goal.get('cover',{})
  cover_ok=True
  for field in covers:
   required=set(covers[field])
   present=set(opt[field] for opt in combo)
   if not required.issubset(present):
    cover_ok=False
    break
  if not cover_ok:
   continue
  # Check no conflicts
  conflict_found=False
  for i in range(len(combo)):
   for j in range(i+1,len(combo)):
    if combo[j]['id'] in combo[i]['conflicts'] or combo[i]['id'] in combo[j]['conflicts']:
     conflict_found=True
     break
   if conflict_found:
    break
  if conflict_found:
   continue
  # Check closed dependencies
  if goal.get('closed_dependencies',False):
   all_reqs=set()
   for opt in combo:
    all_reqs.update(opt['requires'])
   ids_set=set(ids)
   if not all_reqs.issubset(ids_set):
    continue
  # Check sum_bounds
  sum_bounds=goal.get('sum_bounds',{})
  sum_ok=True
  for field in sum_bounds:
   vals=[opt.get(field,0) for opt in combo]
   s=sum(vals)
   if 'min' in sum_bounds[field] and s<sum_bounds[field]['min']:
    sum_ok=False
    break
   if 'max' in sum_bounds[field] and s>sum_bounds[field]['max']:
    sum_ok=False
    break
  if not sum_ok:
   continue
  # Check order_by ascending lex
  order_by=goal.get('order_by',[])
  if order_by:
   sorted_combo=sorted(combo,key=lambda x: tuple(x[field] for field in order_by))
   if [opt['id'] for opt in sorted_combo]!=ids:
    continue
  # Valid candidate
  if valid(ids):
   result=ids
   break
 if result:
  break

